import { ContainerModule } from 'inversify';

import { AssetManager } from '@game-studio/asset-manager';
import { SoundManager } from '@game-studio/sound-manager';
import { ESSessionDataVue, ITSessionDataVue, UKSessionDataVue, BasicSessionDataVue } from '@game-studio/overlays';
import { GameInGameManager } from '@game-studio/game-in-game';

import { default as AppComponent } from '../views/app-view/app.vue';
import { default as GameView } from '../views/game/game-view.vue';
import { default as DesktopHowToPlay } from '../views/how-to-play/desktop/desktop-htp.vue';
import { default as MobileHowToPlay } from '../views/how-to-play/mobile/mobile-htp.vue';
import { default as NewHowToPlay } from '../views/new-htp/how-to-play.vue';

import { getCabinetConfig } from '../cabinet/configs/cabinet-config';
import { stake } from '../cabinet/stake';
import { gameConfig } from '../models/config-model';
import { CurrencyFormatter } from '../currency/currency-formatter';
import { getCurrencySettings } from '../currency/currency-settings';
import { getEndpoints } from '../endpoints/endpoints';
import { GameConnectionFactory } from '../frame-connection/game-connection-factory';
import { BaseGameServer } from '../game-server/game-server';
import { inversifyContainer } from '../inversify/container';
import { Injects } from '../inversify/injects';
import { BaseAdminSettings } from '../services/admin-settings';
import { device } from '../services/device';
import { environment } from '../services/environment';
import { GameConfigProvider } from '../services/game-config-provider';
import { queryStringParams } from '../services/query-string';
import { createBaseLog } from '../services/utilities';
import { IEndpoints, ITranslationVersions } from '../types';
import { MINIMUM_TRANSLATION_VERSIONS } from '../config/translation-versions';
import { OperatorModel } from '../models/operator-model';
import { PrizeLeagueManager } from '../services/prize-league/prize-league-manager';

export const containerModule = new ContainerModule((bind) => {
    const soundManager = new SoundManager({ disableAutoPause: true });
    const frameConnection = GameConnectionFactory.create();
    const endpointsFactory = getEndpoints;
    const urls = endpointsFactory().urls[environment];

    bind(Injects.FrameConnection).toConstantValue(frameConnection);
    bind(Injects.AppComponent).toConstantValue(AppComponent);
    bind(Injects.GameComponent).toConstantValue(GameView);
    bind(Injects.DesktopHTPComponent).toConstantValue(DesktopHowToPlay);
    bind(Injects.MobileHTPComponent).toConstantValue(MobileHowToPlay);
    bind(Injects.VueHTPComponent).toConstantValue(NewHowToPlay);
    switch (queryStringParams.locale) {
        case 'it-it':
            bind(Injects.SessionDataComponent).toConstantValue(ITSessionDataVue);
            break;
        case 'es-es':
            bind(Injects.SessionDataComponent).toConstantValue(ESSessionDataVue);
            break;
        case 'dk-dk':
        case 'se-se':
            bind(Injects.SessionDataComponent).toConstantValue(BasicSessionDataVue);
            break;
        case 'en-gb':
        default:
            bind(Injects.SessionDataComponent).toConstantValue(UKSessionDataVue);
            break;
    }

    bind(Injects.EndPointsFactory).toFunction(endpointsFactory);

    bind(Injects.CurrencySettings).toConstantValue(getCurrencySettings());
    switch (queryStringParams.locale) {
        case 'it-it':
        case 'es-es':
            bind(Injects.CurrencyFormatter).toConstantValue(new CurrencyFormatter(false));
            break;
        default:
            bind(Injects.CurrencyFormatter).toConstantValue(new CurrencyFormatter(true));
    }

    bind(Injects.CabinetBaseOptions).toConstantValue({}); // TODO: Can I Remove This?
    bind(Injects.Stake).toConstantValue(stake);
    bind(Injects.UserPrefsGameName).toConstantValue(gameConfig.gameCategory);
    bind(Injects.SettingsPageGameName).toConstantValue(gameConfig.gameCategory);
    bind(Injects.AssetQualityGetter).toFunction(() => '1');
    bind(Injects.SoundManager).toConstantValue(soundManager);
    bind(Injects.CreateLogBody).toFunction(createBaseLog);

    // Factories
    // bind(Injects.ApiClientFactory).toFactory(() => {
    //     return async () => {
    //         if (isInternationalBuild() && inversifyContainer.frameConnection.parentConstants.isApp) {
    //             bind(Injects.ApiClient).toConstantValue(new HostRequestAdapter());
    //         }
    //     };
    // });
    bind(Injects.AdminSettingsFactory).toFactory(() => {
        return async () => {
            const adminSettings = BaseAdminSettings.Instance;
            await adminSettings.initialise();
            bind(Injects.AdminSettings).toConstantValue(adminSettings);
        };
    });
    bind(Injects.StringsFactory).toFactory(() => {
        return async () => {
            await loadStrings(inversifyContainer.endPoints);
            if (gameConfig.usingCdnStrings) {
                let strings = AssetManager.getJsonData<any>('shared-strings');
                if (gameConfig.features.enableSessionManager) {
                    const sessionStrings = AssetManager.getJsonData<any>('session-strings');
                    strings = deepMergeStrings(strings, sessionStrings);
                }
                const gameStrings = AssetManager.getJsonData<any>('strings');
                strings = deepMergeStrings(strings, gameStrings);

                bind(Injects.Strings).toConstantValue(strings);
            }
            bind(Injects.ErrorStrings).toConstantValue(AssetManager.getJsonData<any>('error-strings'));
            bind(Injects.CabinetConfig).toConstantValue(getCabinetConfig());
        };
    });
    bind(Injects.GameServerFactory).toFactory(() => {
        return async () => {
            bind(Injects.GameServer).toConstantValue(new BaseGameServer());
        };
    });
    bind(Injects.GameConfigProvider).toConstantValue(new GameConfigProvider());

    // actionMenu bindings
    bind(Injects.OperatorFeatureHighlights).toConstantValue({
        gameInGame: true
    });
    bind(Injects.LocaleFeatures).toConstantValue({
        arcadeHasBonusInPlayApi: true,
        hasGameInGameFreeze: true
    });
    bind(Injects.GameInGameManager).toConstantValue(new GameInGameManager({
        device,
        locale: queryStringParams.locale,
        apiDomain: urls.platform,
        gigConfigDomain: urls.gameInGame,
        operator: queryStringParams.operator,
        gameName: gameConfig.engineName,
        gameGuid: gameConfig.gameGuid,
        gameConnection: frameConnection,
        host: queryStringParams.launchedFrom === 'arcade' ? 'arcade' : 'bingo',
        checkForBonusRounds: true
    }));

    bind(Injects.OperatorModel).to(OperatorModel).inSingletonScope();
    bind(Injects.PrizeLeagueManager).to(PrizeLeagueManager).inSingletonScope();
});

function mergeWithMinimumVersions(): ITranslationVersions | undefined {
    const versions = inversifyContainer.translationVersions;
    const locale = queryStringParams.locale;

    if (!versions) { return undefined; }

    const minimumVersions = MINIMUM_TRANSLATION_VERSIONS[locale];

    return {
        game: versions.game, // Game controls its own version
        shared: Math.max(versions.shared, minimumVersions.shared),
        errors: Math.max(versions.errors, minimumVersions.errors),
        chatRules: Math.max(versions.chatRules, minimumVersions.chatRules),
        session: Math.max(versions.session ?? 0, minimumVersions.session ?? 0)
    };
}

function loadStrings(endpoints: IEndpoints): ReturnType<typeof AssetManager.load> {
    const adminSettings = inversifyContainer.adminSettings;
    const versions = mergeWithMinimumVersions();
    const useNewPath = versions !== undefined;
    const errorStringsPath = useNewPath ? `arcade-errors/${versions.errors}/translations.json` : `shared/${adminSettings.errorStrings}/error-strings.json`;
    const gameStringsPath = useNewPath ? `${endpoints.urls[environment].cdnGameName}${versions.game}/translations.json` : `${endpoints.urls[environment].cdnGameName}core/${adminSettings.assetVersion.core}/strings.json`;
    const sharedStringsPath = useNewPath ? `arcade-shared/${versions.shared}/translations.json` : `shared/${adminSettings.sharedStrings}/shared-strings.json`;
    const sessionStringsPath = useNewPath ? `session/${versions.session}/translations.json` : `shared/${adminSettings.sharedStrings}/session-strings.json`;

    const data = {
        baseUrl: useNewPath ? endpoints.urls[environment].cdnTranslationsRoot : endpoints.urls[environment].cdnRoot,
        version: '',
        skin: '',
        assetList: {
            data: [
                { name: 'error-strings', url: errorStringsPath }
            ]
        }
    };

    if (!inversifyContainer.isBound(Injects.Strings)) {
        gameConfig.usingCdnStrings = true;
        data.assetList.data.push({ name: 'strings', url: gameStringsPath });
        data.assetList.data.push({ name: 'shared-strings', url: sharedStringsPath });
    }
    if (gameConfig.features.enableSessionManager) {
        data.assetList.data.push({ name: 'session-strings', url: sessionStringsPath });
    }

    return AssetManager.load(data);
}

function deepMergeStrings(current: Record<string, string> | string, update: Record<string, string> | string) {
    if (typeof current === 'string' || typeof update === 'string') {
        current = update;
    } else {
        for (const key of Object.keys(update)) {
            if (!Object.prototype.hasOwnProperty.call(current, key) || typeof update[key] !== 'object' || typeof current[key] !== 'object') current[key] = update[key];
            else deepMergeStrings(current[key], update[key]);
        }
    }

    return current;
}
